using System;
using System.Collections.Generic;

class Fighter
{
    public string Name;
    public int Hp;
    public int MaxHp;
    public int Attack;
    public List<string> Items = new() { "Potion" };

    public Fighter(string name, int hp, int attack)
    {
        Name = name;
        Hp = hp;
        MaxHp = hp;
        Attack = attack;
    }

    public bool IsDead()
    {
        return Hp <= 0;
    }
}

public int MakeDamage(Random random)
{
    return random.Next(Attack - 2, Attack + 3);
}

public void TakeDamage(int damage)
{
    Hp -= damage;
    if (Hp < 0) Hp = 0;
}

public bool UsePotion()
{
    if (!Items.Contains("Potion")) return false;

    Hp += 10;
    if (Hp > MaxHp) Hp = MaxHp;
    Items.Remove("Potion");
    return true;
}

class Program
{
    static void Main()
    {
        Random random = new();
        Fighter player = new("Player", 30, 8);
        Fighter monster = new("Slime", 25, 6);

        while (!player.IsDead() && !monster.IsDead())
        {
            Console.WriteLine($"플레이어: {player.Hp}");
            Console.WriteLine($"몬스터: {monster.Hp}");
            Console.Write("1. 공격  2. 회복: ");

            string input = Console.ReadLine();

            if (input == "1")
            {
                int damage = player.MakeDamage(random);
                monster.TakeDamage(damage);
                Console.WriteLine($"{damage} 피해");
            }

            else if (input == "2")
            {
                bool used = player.UsePotion();
                if (!used) Console.WriteLine("물약이 없습니다.");
            }
            else
            {
                Console.WriteLine("다시 입력하세요.");
                continue;
            }

            if (!monster.IsDead())
            {
                int damage = monster.MakeDamage(random);
                player.TakeDamage(damage);
                Console.WriteLine($"몬스터의 {damage} 피해");
            }
        }

        if (monster.IsDead()) Console.WriteLine("승리");
        else Console.WriteLine("게임 오버");
    }
}
